mapper.select:
SELECT ,
       c.CUSTOMER_NAME
FROM TBL_AR_ADVANCE_RECEIPT a
LEFT JOIN TBL_AR_CUSTOMER c ON a.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0
WHERE a.IS_DELETED = 0

    AND a.ADVANCE_NO LIKE '%' || #{param.advanceNo} || '%'


    AND a.CUSTOMER_ID = #{param.customerId}


    AND a.ADVANCE_STATUS = #{param.advanceStatus}


    AND a.ADVANCE_DATE >= TO_DATE(#{param.startDate}, 'YYYY-MM-DD')


    AND a.ADVANCE_DATE <= TO_DATE(#{param.endDate}, 'YYYY-MM-DD')


    AND a.TENANT_ID = #{param.tenantId}


    AND a.ORG_ID = #{param.orgId}

ORDER BY a.CREATE_TIME DESC

SELECT ,
       c.CUSTOMER_NAME
FROM TBL_AR_ADVANCE_RECEIPT a
LEFT JOIN TBL_AR_CUSTOMER c ON a.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0
WHERE a.IS_DELETED = 0

    AND a.ADVANCE_NO LIKE '%' || #{param.advanceNo} || '%'


    AND a.CUSTOMER_ID = #{param.customerId}


    AND a.ADVANCE_STATUS = #{param.advanceStatus}


    AND a.TENANT_ID = #{param.tenantId}

ORDER BY a.CREATE_TIME DESC

SELECT 
FROM TBL_AR_ADVANCE_RECEIPT a
WHERE a.ADVANCE_NO = #{advanceNo}
    AND a.TENANT_ID = #{tenantId}
    AND a.IS_DELETED = 0

SELECT 
FROM TBL_AR_ADVANCE_RECEIPT a
WHERE a.CUSTOMER_ID = #{customerId}
    AND a.TENANT_ID = #{tenantId}
    AND a.IS_DELETED = 0
ORDER BY a.CREATE_TIME DESC

SELECT COUNT(*) AS totalCount, NVL(SUM(ADVANCE_AMOUNT), 0) AS totalAdvanceAmount, NVL(SUM(OFFSET_AMOUNT), 0) AS totalOffsetAmount, NVL(SUM(REMAINING_AMOUNT), 0) AS totalRemainingAmount FROM TBL_AR_ADVANCE_RECEIPT WHERE IS_DELETED = 0
AND TENANT_ID = #{param.tenantId}
AND CUSTOMER_ID = #{param.customerId}
